-- =====================================================================
--  Chantier Belém — base de données Supabase
--  À coller en entier dans Supabase > SQL Editor > New query > Run.
--  Le compte administrateur (maître d'ouvrage) est l'adresse ci-dessous :
--  modifiez-la AVANT d'exécuter si vous utiliserez une autre adresse.
-- =====================================================================

create or replace function public.admin_email() returns text
language sql immutable as $$ select 'bpelouin@icloud.com'::text $$;

-- ---------- Profils ----------
create table if not exists public.profiles (
  id uuid primary key references auth.users(id) on delete cascade,
  email text,
  name text default '',
  company text default '',
  phone text default '',
  role text not null default 'pending',          -- admin | entrepreneur | st | moe | csp | pending
  lots text[] not null default '{}',
  approved boolean not null default false,
  requested boolean not null default false,       -- a demandé l'accès
  req_role text default '',
  req_note text default '',
  created_at timestamptz default now(),
  updated_at timestamptz default now()
);

create or replace function public.is_admin() returns boolean
language sql stable security definer set search_path = public as $$
  select exists (select 1 from profiles where id = auth.uid() and role = 'admin' and approved);
$$;
create or replace function public.is_member() returns boolean
language sql stable security definer set search_path = public as $$
  select exists (select 1 from profiles where id = auth.uid() and approved);
$$;
create or replace function public.admin_id() returns uuid
language sql stable security definer set search_path = public as $$
  select id from profiles where role = 'admin' and approved order by created_at limit 1;
$$;

-- création automatique du profil à l'inscription
create or replace function public.handle_new_user() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  insert into profiles (id, email, name, role, approved)
  values (new.id, lower(new.email), coalesce(new.raw_user_meta_data->>'name', ''),
          case when lower(new.email) = lower(admin_email()) then 'admin' else 'pending' end,
          lower(new.email) = lower(admin_email()));
  return new;
end $$;
drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created after insert on auth.users
  for each row execute function public.handle_new_user();

-- un non-administrateur ne peut pas changer son rôle, ses lots ni sa validation
create or replace function public.guard_profile() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if not is_admin() then
    new.role := old.role; new.approved := old.approved; new.lots := old.lots; new.email := old.email;
  end if;
  new.updated_at := now();
  return new;
end $$;
drop trigger if exists guard_profile on public.profiles;
create trigger guard_profile before update on public.profiles
  for each row execute function public.guard_profile();

alter table public.profiles enable row level security;
drop policy if exists p_sel on public.profiles;
create policy p_sel on public.profiles for select using (id = auth.uid() or is_admin() or (approved and is_member()));
drop policy if exists p_upd on public.profiles;
create policy p_upd on public.profiles for update using (id = auth.uid() or is_admin());
drop policy if exists p_del on public.profiles;
create policy p_del on public.profiles for delete using (is_admin() and role <> 'admin');

-- ---------- Contenus publics (journal, livre, réserves, documents, questions, avancement) ----------
create table if not exists public.pub (
  author uuid not null references auth.users(id) on delete cascade,
  id text not null,
  kind text,
  data jsonb not null default '{}',
  created_at timestamptz default now(),
  updated_at timestamptz default now(),
  primary key (author, id)
);
alter table public.pub enable row level security;
drop policy if exists pub_sel on public.pub;
create policy pub_sel on public.pub for select using (is_member());
drop policy if exists pub_ins on public.pub;
create policy pub_ins on public.pub for insert with check (author = auth.uid() and is_member());
drop policy if exists pub_upd on public.pub;
create policy pub_upd on public.pub for update using ((author = auth.uid() and is_member()) or is_admin());
drop policy if exists pub_del on public.pub;
create policy pub_del on public.pub for delete using ((author = auth.uid() and is_member()) or is_admin());

-- ---------- Contenus chiffrés de chaque entreprise (devis, TS, situations) : auteur + administrateur ----------
create table if not exists public.priv (
  author uuid not null references auth.users(id) on delete cascade,
  id text not null,
  kind text,
  data jsonb not null default '{}',
  created_at timestamptz default now(),
  updated_at timestamptz default now(),
  primary key (author, id)
);
-- ---------- Ce que l'administrateur accorde à une entreprise (décisions, montants des bons) ----------
create table if not exists public.granted (
  member uuid not null references auth.users(id) on delete cascade,
  id text not null,
  kind text,
  data jsonb not null default '{}',
  created_at timestamptz default now(),
  updated_at timestamptz default now(),
  primary key (member, id)
);
alter table public.priv enable row level security;
alter table public.granted enable row level security;
drop policy if exists priv_sel on public.priv;
create policy priv_sel on public.priv for select using (author = auth.uid() or is_admin());
drop policy if exists priv_ins on public.priv;
create policy priv_ins on public.priv for insert with check (author = auth.uid() and is_member());
drop policy if exists priv_upd on public.priv;
create policy priv_upd on public.priv for update using (
  is_admin() or (author = auth.uid() and is_member() and not exists (
    select 1 from public.granted g where g.member = priv.author and g.id = 'dec_' || priv.kind || '_' || priv.id)));
drop policy if exists priv_del on public.priv;
create policy priv_del on public.priv for delete using (
  is_admin() or (author = auth.uid() and is_member() and not exists (
    select 1 from public.granted g where g.member = priv.author and g.id = 'dec_' || priv.kind || '_' || priv.id)));
drop policy if exists gr_sel on public.granted;
create policy gr_sel on public.granted for select using (member = auth.uid() or is_admin());
drop policy if exists gr_all on public.granted;
create policy gr_all on public.granted for all using (is_admin()) with check (is_admin());

-- ---------- Données communes écrites par l'administrateur (projet, lots, planning, bons, réunions, visas) ----------
create table if not exists public.shared (
  kind text not null,
  id text not null,
  data jsonb not null default '{}',
  created_at timestamptz default now(),
  updated_at timestamptz default now(),
  primary key (kind, id)
);
alter table public.shared enable row level security;
drop policy if exists sh_sel on public.shared;
create policy sh_sel on public.shared for select using (is_member());
drop policy if exists sh_all on public.shared;
create policy sh_all on public.shared for all using (is_admin()) with check (is_admin());

-- ---------- Finances : administrateur seul ----------
create table if not exists public.fin (
  kind text not null,
  id text not null,
  data jsonb not null default '{}',
  created_at timestamptz default now(),
  updated_at timestamptz default now(),
  primary key (kind, id)
);
alter table public.fin enable row level security;
drop policy if exists fin_all on public.fin;
create policy fin_all on public.fin for all using (is_admin()) with check (is_admin());

-- ---------- Fichiers (photos, plans) ----------
insert into storage.buckets (id, name, public) values ('chantier', 'chantier', false)
  on conflict (id) do nothing;
drop policy if exists st_sel on storage.objects;
create policy st_sel on storage.objects for select using (bucket_id = 'chantier' and public.is_member());
drop policy if exists st_ins on storage.objects;
create policy st_ins on storage.objects for insert with check (bucket_id = 'chantier' and public.is_member());
drop policy if exists st_del on storage.objects;
create policy st_del on storage.objects for delete using (bucket_id = 'chantier' and (owner = auth.uid() or public.is_admin()));

-- fin du script

